/**
 * Invoice Types — Sawaa Dashboard
 *
 * The wire shapes are DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change becomes a type error here instead of drifting
 * silently. Query and UI-only types stay local.
 *
 * Money: `subtotal` / `vatAmt` / `total` / `refundedAmount` are Prisma
 * `Decimal`s — decimal strings on the wire, exactly as documented. The one
 * exception is `toInvoiceListItem`, which parses them for the table.
 */

import type { components } from "@/lib/types/api.generated"
import type { PaginatedQuery } from "./common"

type Schemas = components["schemas"]

/* ─── Entities (derived from OpenAPI) ─── */

/** `GET /dashboard/finance/invoices` row (`InvoiceListRowDto`). */
export type InvoiceListRow = Schemas["InvoiceListRowDto"]

/** `GET /dashboard/finance/invoices` envelope (`InvoiceListResponseDto`). */
export type InvoiceListPage = Schemas["InvoiceListResponseDto"]

/** `POST /dashboard/finance/invoices` and `PATCH …/discount` (`InvoiceRecordDto`). */
export type InvoiceRecord = Schemas["InvoiceRecordDto"]

/** `GET /dashboard/finance/invoices/:id` (`InvoiceDetailResponseDto`). */
export type InvoiceDetail = Schemas["InvoiceDetailResponseDto"]

/** `GET|POST /dashboard/finance/invoices/:id/pdf` — presigned URL. */
export type InvoicePdfUrl = Schemas["InvoicePdfUrlDto"]

/** `POST /dashboard/finance/bookings/:bookingId/invoice` (`EnsuredInvoiceDto`). */
export type EnsuredBookingInvoice = Schemas["EnsuredInvoiceDto"]

/** Invoice status vocabulary, as the snapshot's `InvoiceStatus` enum. */
export type InvoiceStatus = Schemas["InvoiceStatus"]

/* ─── Query (client-side; mapped onto ListInvoicesDto by lib/api/invoices) ─── */

export interface InvoiceListQuery extends PaginatedQuery {
  /** Page size sent to the backend list endpoint (mirrors PaginationDto.limit). */
  limit?: number
  search?: string
  status?: InvoiceStatus
  clientId?: string
  bookingId?: string
  dateFrom?: string
  dateTo?: string
}

/* ─── UI projection ─── */

/**
 * Flat list-row type consumed by the invoice table + columns. Produced once by
 * `toInvoiceListItem` from `InvoiceListRow`; it is a UI projection, not a wire
 * shape.
 */
export interface InvoiceListItem {
  id: string
  invoiceNumber: string
  clientName: string | null
  totalAmount: number
  taxAmount: number | null
  createdAt: string
  status: InvoiceStatus
  sentAt: string | null
  hasPdf: boolean
}
